const r="zenkamoku-n2-best-workbook",b="w11-d03",a=11,p=3,o="第11週",u="3日目",t="即時応答",n="Quick response",c="listening_response",e="p.185",i=[{number:1,trackId:"N2-113",audioSrc:"/audio/zenkamoku_n2/N2-113.mp3",options:["1","2","3"],correct:3,correctOption:"3",script:"男この仕事は経験を問わずご応募いただけま<br />すよ<br />女1どんな経験が要なんてすか<br />2やばリ素人には難しそうてすね<br />3それなら私にもチンスがあリますね<br />[幻<br />3N2-114答え1<br />女加藤さんは日として学校を休まなかた<br />んだて<br />男1なかなかてきるとじなよね<br />こゃい<br />2その時はどうして休んじたの?<br />3のんびリした人だからね<br />3N2-115答え1<br />男：彼久しぶリにテスをして嬉しそうだね<br />女1うんいきいきしてるね<br />2うんちくちだね<br />めゃゃ<br />3うんうろうろしてるね<br />女うう<br />この公園の桜も咲ことしてるね<br />男1じお花見はまだまだすと先だね<br />2もと早く見にくればよかたね<br />3来週には花が見られそうだね",explanation:"<b>【正解】3</b><br/>～を問<br/>と<br/>わず＝～に関係なく 和～无关"},{number:2,trackId:"N2-114",audioSrc:"/audio/zenkamoku_n2/N2-114.mp3",options:["1","2","3"],correct:1,correctOption:"1",script:"",explanation:"<b>【正解】1</b><br/>～として…ない：全く…ない。没有一～…；从来没有～…过<br/>※～には１と助数詞が入る。例えば「一人」「一つ」<br/>「一日」など。前接1 和量词，如“一つ”“一人”“一日”等"},{number:3,trackId:"N2-115",audioSrc:"/audio/zenkamoku_n2/N2-115.mp3",options:["1","2","3"],correct:1,correctOption:"1",script:"",explanation:"<b>【正解】1</b><br/>いきいき：元気がよくて勢いのある様子 栩栩如生；鲜活"},{number:4,trackId:"N2-116",audioSrc:"/audio/zenkamoku_n2/N2-116.mp3",options:["1","2","3"],correct:3,correctOption:"3",script:"",explanation:"<b>【正解】3</b><br/>～ようとしている＝もうすぐ～する 马上要（做）～"},{number:5,trackId:"N2-117",audioSrc:"/audio/zenkamoku_n2/N2-117.mp3",options:["1. てれてか","2. そうだね私も感動て涙が止まらなか","3. 本当時間の無駄だたよね"],correct:2,correctOption:"2. そうだね私も感動て涙が止まらなか",script:"男：言い訳しないてよ<br />女納得しくよた<br />1てれてか<br />2や本当のことだから<br />3遠慮してるわけじゃなよ<br />3N2-118答え1<br />女あとは結果を待のみだね<br />男：1うん楽しみだな<br />2うん頑張らなと<br />3うん忙しね<br />巨]3N2-119<br />答え3<br />男なんくだらな映画だたね<br />:かい<br />女1うんとても勉強になたね<br />2そうだね私も感動て涙が止まらなか<br />3本当時間の無駄だたよね",explanation:"<b>【正解】2. そうだね私も感動て涙が止まらなか</b><br/>言<br/>い<br/>い訳<br/>わけ<br/>：何かをしなければならなかった事情や何かが起<br/>こってしまった事情を説明すること。またその説明<br/>说辞；借口"},{number:6,trackId:"N2-118",audioSrc:"/audio/zenkamoku_n2/N2-118.mp3",options:["1","2","3"],correct:1,correctOption:"1",script:"",explanation:"<b>【正解】1</b><br/>～のみ＝～だけ 只；仅"},{number:7,trackId:"N2-119",audioSrc:"/audio/zenkamoku_n2/N2-119.mp3",options:["1","2","3"],correct:3,correctOption:"3",script:"",explanation:"<b>【正解】3</b><br/>くだらない：ばからしい様子 真面目に取り合うほどの<br/>=== Page 275 ===<br/>価値がない様子 无聊的；无意义的"},{number:8,trackId:"N2-120",audioSrc:"/audio/zenkamoku_n2/N2-120.mp3",options:["1","2","3"],correct:1,correctOption:"1",script:"え1<br />女昨横たたんち<br />:日はべッドにになと眠ゃ<br />男相当疲れてたんだね<br />2べッド寝なと体に悪よ<br />3よく眠れなならホトミルクを飲む<br />いッ<br />とよ<br />いい<br />[国答え3",explanation:"<b>【正解】1</b><br/>～たとたん＝～するとすぐに 刚～就"},{number:9,trackId:"N2-121",audioSrc:"/audio/zenkamoku_n2/N2-121.mp3",options:["1","2","3"],correct:3,correctOption:"3",script:"男週末はずとこのゲムをやてたよ<br />女1なんだか気になるね<br />2えしんだ<br />っこいね<br />3ずぶんはまてるね<br />囮答",explanation:"<b>【正解】3</b><br/>はまる：特に趣味などについて、非常に好きになって、<br/>やめられなくなること 迷上；沉迷"},{number:10,trackId:"N2-122",audioSrc:"/audio/zenkamoku_n2/N2-122.mp3",options:["1","2","3"],correct:1,correctOption:"1",script:"え1<br />女け自だ<br />:運動にかては信があるん<br />男1体力もあて足も速もんね<br />3運動不足なんだと思うよ<br />ロ答え2",explanation:"<b>【正解】1</b><br/>～にかけては：～についてはほかの人より上手だという<br/>表現（表示比其他人好，后接褒义）在～方面；关于～"},{number:11,trackId:"N2-123",audioSrc:"/audio/zenkamoku_n2/N2-123.mp3",options:["1","2","3"],correct:2,correctOption:"2",script:"男べトは私家族たな存在てす<br />:ッにとてみい<br />女1家族以上に大切なんてすね<br />2いなくてはならない存在なんすね<br />3誰よリも会話弾む相手なんてす<br />がね",explanation:"<b>【正解】2</b><br/>～にとって＝～の立場から考えると 对于～；站在～的角度<br/>来说"},{number:12,trackId:"N2-124",audioSrc:"/audio/zenkamoku_n2/N2-124.mp3",options:["1","2","3"],correct:3,correctOption:"3",script:"女：今回のことてわかたてしよ嘘なんかっく<br />もじなよ<br />のゃい<br />男1うんそんな人じなと思てたんだ<br />ゃい<br />けど<br />2うん僕は本当を言くれて<br />にのことて<br />大丈夫だよ<br />3うんもうそんなことはしなよ<br />responsep.",explanation:"<b>【正解】3</b><br/>～ものではない：当然～してはいけない 禁止～；不应当～"}],s={bookId:r,chapterId:b,week:11,day:3,weekTitle:o,dayTitle:"3日目",sectionTitle:t,sectionTitleEn:n,sectionType:c,pageRef:e,questions:i};export{r as bookId,b as chapterId,p as day,u as dayTitle,s as default,e as pageRef,i as questions,t as sectionTitle,n as sectionTitleEn,c as sectionType,a as week,o as weekTitle};
